-- customer_accounts_schema.sql (task 8.8), idempotent, MariaDB 10.4/10.6. Run before the 8.8 code and before
-- fn_checkreferencedaccount_v5.sql (which needs the new columns). Independent of F15 / F16 (no account is created).
--
-- 1. tblinvoice_header.ReceivableAccountId  - the account the invoice debits; a customer payment credits exactly this
--    account (read on the server). NULL on legacy rows: payment of such an invoice is refused.
-- 2. tblinvoice_details.AccountId           - snapshot of the line's income account at save time (decision 81).
-- 3. tblinvoice_payments.PaymentAccountId   - the cash / bank account the payment debits (decision 76).
-- 4. Money columns -> DECIMAL(18,2) (header exclusiveVat / vat / inclusiveVat, details qty / rate / gross, payments amount)
--    with the exact-cents guard of supplier_accounts_schema.sql (tolerance 0.005 = FLOAT noise).
-- 5. Lookup indexes (payments.invoice_Id, details.header_id, header.congregationId).
-- 6. Views and routines: vw_invoices carries congregationId; getAmountPaid no longer rounds to whole units (it returned
--    DECIMAL(10,0)); sp_getinvoice_due / _fullypaid / _withbalances ignored their congregation parameter and now use it;
--    sp_getcustomerpayments takes the congregation (Report::getpaymentreport passes it).
--
-- NOT changed, on purpose:
--  * No `deleted` column on tblinvoice_header / _details / _payments: customer invoices have no delete (decision 83) and
--    customer payments no edit or delete (decision 2), so nothing is ever soft-deleted and there is nothing to filter.
--  * tblinvoice_header.invoiceNo stays INT NOT NULL: customer invoice numbers are generated by the system (a locked
--    sequence per congregation); nobody types them, so the supplier problem (text numbers into an INT) does not exist.
--
-- Rollback: drop the 3 FKs, indexes and columns; restore the routines / views and the old column types from the cutover
-- backup (a conversion back to FLOAT can lose cents).
DELIMITER $$
DROP PROCEDURE IF EXISTS sp_tmp_customer_accounts_schema$$
CREATE PROCEDURE sp_tmp_customer_accounts_schema()
BEGIN
 DECLARE n INT; DECLARE bad INT;
 SELECT COUNT(*) INTO n FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tblinvoice_header' AND COLUMN_NAME='ReceivableAccountId';
 IF n=0 THEN ALTER TABLE tblinvoice_header ADD ReceivableAccountId INT NULL AFTER vatId; SELECT 'ReceivableAccountId applied' result; ELSE SELECT 'ReceivableAccountId skipped' result; END IF;
 SELECT COUNT(*) INTO n FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tblinvoice_header' AND SEQ_IN_INDEX=1 AND COLUMN_NAME='ReceivableAccountId';
 IF n=0 THEN ALTER TABLE tblinvoice_header ADD KEY IDX_CustInvoice_ReceivableAccountId(ReceivableAccountId); END IF;
 SELECT COUNT(*) INTO n FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='tblinvoice_header' AND CONSTRAINT_NAME='FK_CustInvoice_ReceivableAccount' AND CONSTRAINT_TYPE='FOREIGN KEY';
 IF n=0 THEN ALTER TABLE tblinvoice_header ADD CONSTRAINT FK_CustInvoice_ReceivableAccount FOREIGN KEY(ReceivableAccountId) REFERENCES tblaccounttypes(ID); END IF;
 SELECT COUNT(*) INTO n FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tblinvoice_details' AND COLUMN_NAME='AccountId';
 IF n=0 THEN ALTER TABLE tblinvoice_details ADD AccountId INT NULL AFTER productId; SELECT 'AccountId applied' result; ELSE SELECT 'AccountId skipped' result; END IF;
 SELECT COUNT(*) INTO n FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tblinvoice_details' AND SEQ_IN_INDEX=1 AND COLUMN_NAME='AccountId';
 IF n=0 THEN ALTER TABLE tblinvoice_details ADD KEY IDX_CustDetail_AccountId(AccountId); END IF;
 SELECT COUNT(*) INTO n FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='tblinvoice_details' AND CONSTRAINT_NAME='FK_CustDetail_Account' AND CONSTRAINT_TYPE='FOREIGN KEY';
 IF n=0 THEN ALTER TABLE tblinvoice_details ADD CONSTRAINT FK_CustDetail_Account FOREIGN KEY(AccountId) REFERENCES tblaccounttypes(ID); END IF;
 SELECT COUNT(*) INTO n FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tblinvoice_payments' AND COLUMN_NAME='PaymentAccountId';
 IF n=0 THEN ALTER TABLE tblinvoice_payments ADD PaymentAccountId INT NULL AFTER bankId; SELECT 'PaymentAccountId applied' result; ELSE SELECT 'PaymentAccountId skipped' result; END IF;
 SELECT COUNT(*) INTO n FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tblinvoice_payments' AND SEQ_IN_INDEX=1 AND COLUMN_NAME='PaymentAccountId';
 IF n=0 THEN ALTER TABLE tblinvoice_payments ADD KEY IDX_CustPayment_PaymentAccountId(PaymentAccountId); END IF;
 SELECT COUNT(*) INTO n FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='tblinvoice_payments' AND CONSTRAINT_NAME='FK_CustPayment_PaymentAccount' AND CONSTRAINT_TYPE='FOREIGN KEY';
 IF n=0 THEN ALTER TABLE tblinvoice_payments ADD CONSTRAINT FK_CustPayment_PaymentAccount FOREIGN KEY(PaymentAccountId) REFERENCES tblaccounttypes(ID); END IF;
 SELECT COUNT(*) INTO n FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tblinvoice_payments' AND SEQ_IN_INDEX=1 AND COLUMN_NAME='invoice_Id';
 IF n=0 THEN ALTER TABLE tblinvoice_payments ADD KEY IDX_CustPayment_InvoiceId(invoice_Id); END IF;
 SELECT COUNT(*) INTO n FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tblinvoice_details' AND SEQ_IN_INDEX=1 AND COLUMN_NAME='header_id';
 IF n=0 THEN ALTER TABLE tblinvoice_details ADD KEY IDX_CustDetail_HeaderId(header_id); END IF;
 SELECT COUNT(*) INTO n FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tblinvoice_header' AND SEQ_IN_INDEX=1 AND COLUMN_NAME='congregationId';
 IF n=0 THEN ALTER TABLE tblinvoice_header ADD KEY IDX_CustInvoice_CongregationId(congregationId); END IF;
 SELECT COUNT(*) INTO bad FROM tblinvoice_header WHERE (exclusiveVat IS NOT NULL AND (ABS(exclusiveVat-ROUND(exclusiveVat,2))>.005 OR ABS(exclusiveVat)>=10000000000000000)) OR (vat IS NOT NULL AND (ABS(vat-ROUND(vat,2))>.005 OR ABS(vat)>=10000000000000000)) OR (inclusiveVat IS NOT NULL AND (ABS(inclusiveVat-ROUND(inclusiveVat,2))>.005 OR ABS(inclusiveVat)>=10000000000000000));
 SELECT COUNT(*)+bad INTO bad FROM tblinvoice_details WHERE ABS(qty-ROUND(qty,2))>.005 OR ABS(rate-ROUND(rate,2))>.005 OR ABS(gross-ROUND(gross,2))>.005 OR ABS(qty)>=10000000000000000 OR ABS(rate)>=10000000000000000 OR ABS(gross)>=10000000000000000;
 SELECT COUNT(*)+bad INTO bad FROM tblinvoice_payments WHERE ABS(amount-ROUND(amount,2))>.005 OR ABS(amount)>=10000000000000000;
 IF bad>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='customer money conversion refused: values are not exact cents or exceed DECIMAL(18,2)'; END IF;
 SELECT COUNT(*) INTO n FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tblinvoice_header' AND COLUMN_NAME IN('exclusiveVat','vat','inclusiveVat') AND DATA_TYPE<>'decimal';
 IF n>0 THEN ALTER TABLE tblinvoice_header MODIFY exclusiveVat DECIMAL(18,2) NULL,MODIFY vat DECIMAL(18,2) NULL,MODIFY inclusiveVat DECIMAL(18,2) NULL; SELECT 'header money converted' result; ELSE SELECT 'header money skipped' result; END IF;
 SELECT COUNT(*) INTO n FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tblinvoice_details' AND COLUMN_NAME IN('qty','rate','gross') AND DATA_TYPE<>'decimal';
 IF n>0 THEN ALTER TABLE tblinvoice_details MODIFY qty DECIMAL(18,2) NOT NULL,MODIFY rate DECIMAL(18,2) NOT NULL,MODIFY gross DECIMAL(18,2) NOT NULL; SELECT 'detail money converted' result; ELSE SELECT 'detail money skipped' result; END IF;
 SELECT COUNT(*) INTO n FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tblinvoice_payments' AND COLUMN_NAME='amount' AND DATA_TYPE<>'decimal';
 IF n>0 THEN ALTER TABLE tblinvoice_payments MODIFY amount DECIMAL(18,2) NOT NULL; SELECT 'payment money converted' result; ELSE SELECT 'payment money skipped' result; END IF;
END$$
CALL sp_tmp_customer_accounts_schema()$$
DROP PROCEDURE sp_tmp_customer_accounts_schema$$

DROP FUNCTION IF EXISTS getAmountPaid$$
CREATE FUNCTION getAmountPaid(id INT) RETURNS DECIMAL(18,2) READS SQL DATA
BEGIN
 RETURN COALESCE((SELECT SUM(amount) FROM tblinvoice_payments WHERE invoice_Id=id),0);
END$$
CREATE OR REPLACE VIEW vw_invoices AS
 SELECT h.ID AS ID,h.invoiceDate AS invoiceDate,h.invoiceNo AS invoiceNo,UCASE(c.customerName) AS customer,h.duedate AS duedate,
        h.inclusiveVat-(SELECT IFNULL(SUM(p.amount),0) FROM tblinvoice_payments p WHERE p.invoice_Id=h.ID) AS balance,
        IF(h.status=0,'Unpaid',IF(h.status=1,'Partially Paid','Paid')) AS state,h.status AS status,h.postedBy AS postedBy,h.congregationId AS congregationId
 FROM tblinvoice_header h JOIN tblcustomers c ON h.customerId=c.ID
 ORDER BY h.status,h.invoiceNo DESC$$
DROP PROCEDURE IF EXISTS sp_getinvoice_due$$
CREATE PROCEDURE sp_getinvoice_due(IN cong INT)
BEGIN
 SELECT h.ID,h.invoiceNo,DATE_FORMAT(h.invoiceDate,'%d/%m/%Y') AS invoiceDate,DATE_FORMAT(h.duedate,'%d/%m/%Y') AS duedate,DATEDIFF(CURDATE(),h.duedate) AS duedays,
        UCASE(c.customerName) AS customer,h.inclusiveVat,getinvoice_paid(h.ID) AS amountpaid,getinvoicebalance(h.ID) AS balance
 FROM tblinvoice_header h INNER JOIN tblcustomers c ON h.customerId=c.ID
 WHERE h.status<2 AND h.duedate<CURDATE() AND h.congregationId=cong;
END$$
DROP PROCEDURE IF EXISTS sp_getinvoice_fullypaid$$
CREATE PROCEDURE sp_getinvoice_fullypaid(IN cong INT, startdate DATE, enddate DATE)
BEGIN
 SELECT h.ID,DATE_FORMAT(h.invoiceDate,'%d/%m/%Y') AS invoiceDate,h.invoiceNo,UCASE(c.customerName) AS customer,h.inclusiveVat,getinvoice_paid(h.ID) AS amountpaid
 FROM tblinvoice_header h INNER JOIN tblcustomers c ON h.customerId=c.ID
 WHERE h.status=2 AND h.invoiceDate BETWEEN startdate AND enddate AND h.congregationId=cong;
END$$
DROP PROCEDURE IF EXISTS sp_getinvoice_withbalances$$
CREATE PROCEDURE sp_getinvoice_withbalances(IN cong INT, startdate DATE, enddate DATE)
BEGIN
 SELECT h.ID,DATE_FORMAT(h.invoiceDate,'%d/%m/%Y') AS invoiceDate,h.invoiceNo,UCASE(c.customerName) AS customer,h.inclusiveVat,
        getinvoice_paid(h.ID) AS amountpaid,getinvoicebalance(h.ID) AS balance
 FROM tblinvoice_header h INNER JOIN tblcustomers c ON h.customerId=c.ID
 WHERE h.status<2 AND h.invoiceDate BETWEEN startdate AND enddate AND h.congregationId=cong;
END$$
DROP PROCEDURE IF EXISTS sp_getcustomerpayments$$
CREATE PROCEDURE sp_getcustomerpayments(IN cid INT, IN sdate DATE, IN edate DATE, IN congid INT)
BEGIN
 SELECT DATE_FORMAT(p.paymentDate,'%d/%m/%y') AS PaymentDate,FORMAT(p.amount,2) AS Amount,UCASE(m.paymentMethod) AS PaymentMethod,UCASE(p.paymentReference) AS PayReference
 FROM tblinvoice_payments p INNER JOIN tblinvoice_header h ON p.invoice_Id=h.ID INNER JOIN tblpaymentmethods m ON p.paymentId=m.ID
 WHERE h.customerId=cid AND h.congregationId=congid AND p.paymentDate BETWEEN sdate AND edate
 ORDER BY p.paymentDate;
END$$
DELIMITER ;
SELECT TABLE_NAME,COLUMN_NAME,COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND ((TABLE_NAME='tblinvoice_header' AND COLUMN_NAME IN('ReceivableAccountId','exclusiveVat','vat','inclusiveVat')) OR (TABLE_NAME='tblinvoice_details' AND COLUMN_NAME IN('AccountId','qty','rate','gross')) OR (TABLE_NAME='tblinvoice_payments' AND COLUMN_NAME IN('PaymentAccountId','amount'))) ORDER BY TABLE_NAME,COLUMN_NAME;
SELECT COUNT(*) legacy_customer_invoices_without_receivable_account FROM tblinvoice_header WHERE ReceivableAccountId IS NULL;
